        // ThermalAtmosphereTable's layout: direction rows' sin(elevation), and the ranges for a 40 km far plane
        static readonly (int r, double sine)[] k_DirectionSines = { (0, -1.0), (1, -0.9687519375038751), (63, -6.200012400024778e-05), (64, 6.200012400024778e-05), (126, 0.9687519375038751), (127, 1.0) };
